"""The tp4/s6 window pack (scripts/ci/references/fusion-jobs/S6, generated by make_s6_jobs.py).

ORDER.txt (the window) and ORDER-SHIP.txt (after the owner's approval) list the folder's templates, each on the one image, with totals that match their headers; every NEEDS line names earlier jobs; every smoke
job carries the two Swift checkpoint keys, every replay and build job none (the job reader refuses the keys beside those steps); the pairs differ by the profile alone and the control of both is the ship-5 profile;
every template parses through the job reader with rc 0 (the ship build excepted: refused while the waiver is PENDING, by design); the pack is what the generator makes; nothing in it names a host, an address or
a registry."""

import json
from pathlib import Path
import re
import subprocess
import sys
import unittest

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import agent_turns  # noqa: E402
import c2_serving_job as job  # noqa: E402
import make_s6_jobs as pack  # noqa: E402
import serving_c2_contract as contract  # noqa: E402

PACK = pack.FOLDER
READER = HERE / 'c2_serving_job.py'
PROFILES = HERE / 'qwen_c2_profiles.json'
CATALOG = json.loads((HERE / 'qwen_c2_checkpoints.json').read_text(encoding='utf-8'))
SWIFT = CATALOG['checkpoints'][0]

# job -> (serves Swift, profile, smoke tests)
EXPECTED = {
    'B0-build-window': (False, '', ''),
    'X0-status-rescan-reset': (False, '', ''),
    'A1-s6-audited-attach': (True, pack.AUDIT, pack.A1_TESTS),
    'T1A-s5-control': (True, pack.SHIP5, pack.T1_TESTS),
    'T1B-s6-candidate': (True, pack.SHIP6, pack.T1_TESTS),
    'T2A-s5-control-8': (True, pack.SHIP5, pack.T2_TESTS),
    'T2B-s6-candidate-8': (True, pack.SHIP6, pack.T2_TESTS),
    'B1-ship-build': (False, '', ''),
    'SR-platform-replay': (False, '', ''),
    'Z-reset': (False, '', ''),
}
WINDOWS = {
    'ORDER.txt': ['B0-build-window', 'X0-status-rescan-reset', 'A1-s6-audited-attach', 'T1A-s5-control', 'T1B-s6-candidate', 'T2A-s5-control-8', 'T2B-s6-candidate-8', 'Z-reset'],
    'ORDER-SHIP.txt': ['B1-ship-build', 'SR-platform-replay'],
}


def order_lines(name):
    return [line.split() for line in (PACK / name).read_text(encoding='utf-8').splitlines() if line.strip() and not line.startswith('#')]


def directives(name, prefix):
    return [line[len(prefix):].split() for line in (PACK / name).read_text(encoding='utf-8').splitlines() if line.startswith(prefix)]


def values(name):
    return job.parse_env((PACK / (name + '.env')).read_text(encoding='utf-8'))


def run_reader(path):
    result = subprocess.run([sys.executable, '-B', '-s', str(READER), str(path), str(PROFILES)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
    return result.returncode, (result.stdout + result.stderr).decode('utf-8', 'replace')


class OrderTests(unittest.TestCase):
    def test_the_orders_list_exactly_the_folders_templates_on_one_image(self):
        self.assertEqual(sorted(path.stem for path in PACK.glob('*.env')), sorted(EXPECTED))
        self.assertEqual(sorted(path.name for path in PACK.glob('*.txt')), sorted(WINDOWS))
        listed = set()
        for name, jobs in WINDOWS.items():
            rows = order_lines(name)
            self.assertEqual([row[0] for row in rows], jobs, name)
            self.assertEqual({row[2] for row in rows}, {pack.IMAGE}, name)
            listed |= set(jobs)
        self.assertEqual(listed, set(EXPECTED))
        self.assertEqual(pack.IMAGE, 'tp4-s6-1', 'the placeholder tag of the manifest')
        for name in EXPECTED:
            self.assertEqual(values(name)['C2_IMAGE_TAG'], pack.IMAGE)

    def test_the_modes_and_the_stop_rules(self):
        modes = {row[0]: row[1] for name in WINDOWS for row in order_lines(name)}
        for key in ('B0-build-window', 'X0-status-rescan-reset', 'A1-s6-audited-attach'):
            self.assertEqual(modes[key], 'stop', key)
        for key in ('T1A-s5-control', 'T1B-s6-candidate', 'Z-reset', 'B1-ship-build', 'SR-platform-replay'):
            self.assertEqual(modes[key], 'soft', key)
        for key in ('T2A-s5-control-8', 'T2B-s6-candidate-8'):
            self.assertEqual(modes[key], 'opt', 'the production-load pair runs when the window has the minutes')
        self.assertEqual(order_lines('ORDER.txt')[-1][0], 'Z-reset', 'the end sequence is last')

    def test_the_header_totals_match_the_minutes(self):
        for name in WINDOWS:
            text = (PACK / name).read_text(encoding='utf-8')
            minutes = sum(int(row[3]) for row in order_lines(name))
            self.assertIn('%d minutes (%d h %d min) in all' % (minutes, minutes // 60, minutes % 60), text, name)
            for row in order_lines(name):
                self.assertIn('%s %s' % (row[0].split('-')[0], row[3]), text, name)
        cards = sum(int(row[3]) for row in order_lines('ORDER.txt') if row[0] != 'B0-build-window')
        self.assertIn('%d minutes of cards' % cards, (PACK / 'ORDER.txt').read_text(encoding='utf-8'))

    def test_the_core_of_the_window_is_the_gates_and_the_decode_pair_and_fits_a_working_night(self):
        minutes = {row[0].split('-')[0]: int(row[3]) for row in order_lines('ORDER.txt')}
        core = minutes['X0'] + minutes['A1'] + minutes['T1A'] + minutes['T1B'] + minutes['Z']
        self.assertLessEqual(core, 270, 'X0 A1 T1A T1B Z')
        self.assertLessEqual(core + minutes['T2A'] + minutes['T2B'], 360, 'with the optional production-load pair')

    def test_needs_lines_name_earlier_jobs_only(self):
        for name in WINDOWS:
            names = [row[0].split('-')[0] for row in order_lines(name)]
            for left_right in directives(name, '# NEEDS '):
                arrow = left_right.index('<-')
                left, right = left_right[:arrow], left_right[arrow + 1:]
                for token in left + right:
                    self.assertIn(token, names, (name, token))
                for later in left:
                    for earlier in right:
                        self.assertLess(names.index(earlier), names.index(later), (name, left_right))
        self.assertEqual(directives('ORDER.txt', '# NEEDS '), [['X0', '<-', 'B0'], ['A1', '<-', 'X0'], ['T1A', '<-', 'A1'], ['T1B', '<-', 'T1A'], ['T2A', '<-', 'T1B'], ['T2B', '<-', 'T2A']])
        self.assertEqual(directives('ORDER-SHIP.txt', '# NEEDS '), [['SR', '<-', 'B1']])

    def test_the_arc_range_covers_every_audited_boot_and_every_timed_job_and_nothing_else(self):
        names = [row[0].split('-')[0] for row in order_lines('ORDER.txt')]
        (first, last), = directives('ORDER.txt', '# ARC-ZERO ')
        self.assertEqual((first, last), ('A1', 'T2B'))
        for token in ('A1', 'T1A', 'T1B', 'T2A', 'T2B'):
            self.assertTrue(names.index(first) <= names.index(token) <= names.index(last), token)
        for token in ('B0', 'X0', 'Z'):
            self.assertFalse(names.index(first) <= names.index(token) <= names.index(last), token)

    def test_the_orders_say_what_is_new_never_push_a_tag_and_keep_the_run_rules(self):
        for name in WINDOWS:
            text = (PACK / name).read_text(encoding='utf-8')
            for phrase in ('never cancel a running card job', 'owner traffic waiver'):
                self.assertIn(phrase, text.lower() if phrase.islower() else text, (name, phrase))
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        for phrase in ('THE NEW DEVICE FACTS', 'ESTIMATES OF THE TESTS', 'agent_turns8', 'prefill_few_decoders', 'NO-GO for the candidate', 'S6.json'):
            self.assertIn(phrase, text)
        self.assertIn('git mv ORDER-SHIP.txt ORDER.txt', (PACK / 'ORDER-SHIP.txt').read_text(encoding='utf-8'))
        for name in EXPECTED:
            self.assertIn('no tag is pushed from the branch by its author', (PACK / (name + '.env')).read_text(encoding='utf-8'))

    def test_the_estimates_of_the_tests_agree_with_the_agent_turns_plan(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        estimates = dict(pack.TEST_MINUTES)
        for name in ('agent_turns', 'agent_turns8'):
            cfg = agent_turns.settings(name, {'SMOKE_AGENT_NONCE': 'abcd1234'})
            found = agent_turns.estimate(cfg, agent_turns.session_targets(cfg, 262144)[0])
            self.assertLessEqual(found['minutes'], estimates[name], 'the pack allows at least the plan estimate (%s)' % name)
            self.assertLessEqual(estimates[name] - found['minutes'], 8, 'and not a wildly larger one (%s)' % name)
            self.assertIn('%s %d' % (name, estimates[name]), text)


class TemplateTests(unittest.TestCase):
    def test_every_template_parses_with_rc_0_but_the_ship_build_which_is_refused_while_pending(self):
        # Decision-agnostic (like test_s5_pack): B1 is refused while the s6 waiver is PENDING and parses once the owner's decision starts APPROVED.
        profiles = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles']
        approved = not contract.traffic_waiver_pending(dict(profiles[pack.SHIP6], name=pack.SHIP6))
        for name in EXPECTED:
            with self.subTest(name=name):
                code, text = run_reader(PACK / (name + '.env'))
                if name == 'B1-ship-build' and not approved:
                    self.assertEqual(code, 1, text)
                    self.assertIn('not APPROVED', text)
                else:
                    self.assertEqual(code, 0, text)

    def test_serving_jobs_carry_the_checkpoint_keys_and_the_expected_profile_and_tests(self):
        for name, (serves_swift, profile, tests) in EXPECTED.items():
            with self.subTest(name=name):
                found = values(name)
                if serves_swift:
                    self.assertEqual((found['C2_MODEL_REPO'], found['C2_MODEL_REVISION']), (SWIFT['repo'], SWIFT['revision']))
                    self.assertEqual((pack.REPO, pack.REVISION), (SWIFT['repo'], SWIFT['revision']))
                else:
                    self.assertNotIn('C2_MODEL_REPO', found)
                    self.assertNotIn('C2_MODEL_REVISION', found)
                self.assertEqual(found.get('C2_PROFILE', ''), profile)
                self.assertEqual(found.get('C2_SMOKE_TESTS', ''), tests)

    def test_the_smoke_names_exist_in_the_harness(self):
        source = (HERE / 'c2_serving_smoke.py').read_text(encoding='utf-8')
        known = set(re.findall(r"record\('([a-z0-9_]+)'", source)) | set(re.findall(r"'(np1_live\d)'", source))
        for name, (_swift, _profile, tests) in EXPECTED.items():
            for test in filter(None, tests.split(',')):
                self.assertTrue(re.search(r"'%s'" % re.escape(test), source) or test in ('warmup', 'coding', 'concurrent8_steady') or test in known, (name, test))
        for test in ('prefill_few_decoders', 'agent_turns', 'agent_turns8'):
            self.assertIn("'%s'" % test, source)
        self.assertIn('agent_turns8', agent_turns.TESTS)

    def test_the_pairs_differ_by_the_profile_alone_and_the_control_is_the_ship_5_profile(self):
        keys = ('C2_SMOKE_TESTS', 'C2_BOX_MINUTES', 'C2_IMAGE_TAG', 'C2_MODEL_REPO', 'C2_MODEL_REVISION', 'C2_CARDS', 'C2_ACTIONS', 'C2_TELEMETRY')
        for control, arm in (('T1A-s5-control', 'T1B-s6-candidate'), ('T2A-s5-control-8', 'T2B-s6-candidate-8')):
            a, b = values(control), values(arm)
            self.assertEqual([a[key] for key in keys], [b[key] for key in keys], control)
            self.assertEqual((a['C2_PROFILE'], b['C2_PROFILE']), (pack.SHIP5, pack.SHIP6), control)
        profiles = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles']
        self.assertFalse(job.bake_waiver_pending(profiles[pack.SHIP5]), 'the control is the APPROVED profile that serves production')
        self.assertTrue(profiles[pack.SHIP5]['owner_traffic_waiver']['decision'].startswith('APPROVED'))

    def test_the_timed_legs_name_the_tests_that_judge_the_candidate(self):
        t1 = values('T1B-s6-candidate')['C2_SMOKE_TESTS'].split(',')
        self.assertEqual(t1[:4], ['warmup', 'np1_live1', 'np1_live2', 'np1_live4'], 'the live counts WC acts at')
        for test in ('prefill_few_decoders', 'concurrent8_steady', 'agent_turns'):
            self.assertIn(test, t1)
        self.assertEqual(t1[-1], 'agent_turns', 'the main judge last')
        self.assertNotIn('agent_turns8', t1, 'agent_turns8 is the production-load pair\'s own')
        t2 = values('T2B-s6-candidate-8')['C2_SMOKE_TESTS'].split(',')
        self.assertEqual(t2, ['warmup', 'concurrent8_steady', 'agent_turns8'])
        a1 = values('A1-s6-audited-attach')['C2_SMOKE_TESTS'].split(',')
        for test in ('np1_live2', 'np1_live4', 'prefill_few_decoders', 'concurrent8_drain', 'concurrent8_steady', 'agent_turns'):
            self.assertIn(test, a1)

    def test_the_audited_attach_runs_the_candidates_audited_twin_inside_a_box_longer_than_its_estimate(self):
        found = values('A1-s6-audited-attach')
        self.assertEqual(found['C2_PROFILE'], pack.AUDIT)
        minutes = {row[0].split('-')[0]: int(row[3]) for row in order_lines('ORDER.txt')}
        self.assertGreater(int(found['C2_BOX_MINUTES']), minutes['A1'])
        for letter in ('T1A', 'T1B', 'T2A', 'T2B'):
            name = next(key for key in EXPECTED if key.startswith(letter))
            self.assertGreater(int(values(name)['C2_BOX_MINUTES']), minutes[letter], name)

    def test_each_smoke_job_names_the_steady_test_and_a_box_inside_the_step(self):
        for name, (_swift, _profile, tests) in EXPECTED.items():
            found = values(name)
            if 'smoke' not in found['C2_ACTIONS'].split():
                continue
            with self.subTest(name=name):
                self.assertIn('concurrent8_steady', tests.split(','), 'the smoke check requires the eight-seat test on this profile')
                self.assertTrue(0 < int(found['C2_BOX_MINUTES']) <= 210)
                self.assertEqual(found['C2_CARDS'], 'quad')
                self.assertEqual(found['C2_TELEMETRY'], '1')

    def test_no_checkpoint_job_uses_a_step_that_does_not_forward_the_checkpoint(self):
        for name in EXPECTED:
            actions = set(values(name)['C2_ACTIONS'].split())
            if values(name).get('C2_MODEL_REPO'):
                self.assertFalse(actions - set(job.MODEL_ACTIONS), name)
            if actions & {'replay', 'build', 'fabric'}:
                self.assertNotIn('C2_MODEL_REPO', values(name), name)

    def test_the_build_bakes_the_ship_5_profile_with_the_oneq_graft_and_the_ship_build_the_candidate(self):
        found = values('B0-build-window')
        self.assertEqual((found['C2_BAKE_DEFAULT_PROFILE'], found['C2_BAKE_GRAFT']), (pack.SHIP5, 'K64j-OQ'))
        profiles = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles']
        self.assertFalse(job.bake_waiver_pending(profiles[pack.SHIP5]), 'the ship-5 waiver is APPROVED: the window build is not refused')
        ship = values('B1-ship-build')
        self.assertEqual((ship['C2_BAKE_DEFAULT_PROFILE'], ship['C2_BAKE_GRAFT']), (pack.SHIP6, 'K64j-OQ'))
        self.assertEqual(job.bake_waiver_pending(profiles[pack.SHIP6]), profiles[pack.SHIP6]['owner_traffic_waiver']['decision'].startswith('PENDING'))
        for name in EXPECTED:
            if name not in ('B0-build-window', 'B1-ship-build'):
                self.assertNotIn('C2_BAKE_DEFAULT_PROFILE', values(name), name)

    def test_the_platform_replay_is_the_candidates_and_waits_for_its_approval(self):
        found = values('SR-platform-replay')
        self.assertEqual((found['C2_ACTIONS'], found['C2_REPLAY_PROFILE'], found['C2_PLATFORM_IMAGE']), ('reset replay', pack.SHIP6, 'local:thin-layer'))
        text = (PACK / 'SR-platform-replay.env').read_text(encoding='utf-8')
        self.assertIn('AFTER THE OWNER APPROVES', text)
        self.assertIn('BY THE IMAGE DEFAULT', text)

    def test_the_templates_name_the_lines_the_arms_log_and_the_estimates_are_marked(self):
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'T1B-s6-candidate.env').read_text(encoding='utf-8'))
        for phrase in ('[PINDIAG] tp4 gdn wc engaged', 'reason=8 users (WC takes 2 or 4)', '[PINDIAG] lever N adaptive: decoders<=2 share=0.9 ttft=120 gap_floor=8', 'adaptive=1', 'prefill_ladder_report.py',
                       'np1_report.py', 'octo_compare.py', 'agent_turns.py report', 'ESTIMATE', 'NO-GO for the candidate'):
            self.assertIn(phrase, text)
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'A1-s6-audited-attach.env').read_text(encoding='utf-8'))
        for phrase in ('exact=True', 'audit mismatch', 'reason=8 users', 'adaptive governor', 'about 2.6 GB more DRAM'):
            self.assertIn(phrase, text)
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'T1A-s5-control.env').read_text(encoding='utf-8'))
        self.assertIn('The control logs none of WC', text)


class GeneratedTests(unittest.TestCase):
    def test_the_checked_in_pack_is_what_the_generator_makes(self):
        self.assertEqual(pack.main(['--check']), 0)

    def test_nothing_in_the_pack_names_a_host_an_address_or_a_registry(self):
        for path in PACK.glob('*'):
            text = path.read_text(encoding='utf-8')
            with self.subTest(path=path.name):
                self.assertEqual([needle for needle in ('/home/', 'zot.', 'ghcr', 'docker.io', '.local', '.internal', 'localhost') if needle in text], [])
                self.assertIsNone(re.search(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', text), 'an IP address')
                self.assertIsNone(re.search(r'blackhole-[0-9A-F]{16}', text), 'a card id')
                self.assertIsNone(re.search(r'\bsha256:[0-9a-f]{12,}', text), 'an image digest')
                self.assertNotIn('\r', text)


if __name__ == '__main__':
    unittest.main()
